class Solution {
public:
    int maxCandies(vector<int>& status, vector<int>& candies, vector<vector<int>>& keys, vector<vector<int>>& containedBoxes, vector<int>& initialBoxes) {
        int n = (int)status.size();
        vector<char> haveBox(n, 0), haveKey(n, 0), opened(n, 0);
        queue<int> q;
        for (int b : initialBoxes) {
            haveBox[b] = 1;
            if (status[b] == 1 && !opened[b]) {
                opened[b] = 1;
                q.push(b);
            }
        }
        long long ans = 0;
        while (!q.empty()) {
            int b = q.front(); q.pop();
            ans += candies[b];
            for (int k : keys[b]) {
                haveKey[k] = 1;
                if (haveBox[k] && !opened[k]) {
                    opened[k] = 1;
                    q.push(k);
                }
            }
            for (int c : containedBoxes[b]) {
                haveBox[c] = 1;
                if ((status[c] == 1 || haveKey[c]) && !opened[c]) {
                    opened[c] = 1;
                    q.push(c);
                }
            }
        }
        return (int)ans;
    }
};
